"""FX commission revenue on Spark - the promoted artefact for fx_revenue_calc.

This is the deployment target for the unit once it clears the gate. The pandas
translation under `translator/cache/` is what the equivalence harness scores,
because a Spark session per unit per CI run costs minutes and buys nothing:
both targets are generated from the same legacy source and the same prompt
chain, and `test_spark_matches_pandas_target` in the promotion suite pins them
to each other.

Three things differ from the pandas target, and all three are load-bearing:

  1. Money is summed as DecimalType(18, 6), not double. Floating-point
     addition is not associative, so a double sum over repartitioned data
     drifts in the last cents depending on how Spark split the input - and a
     tolerance wide enough to absorb that is wide enough to hide a real defect.

  2. The unrated-currency path is an explicit `coalesce(rate, lit(0))` rather
     than a join that quietly drops rows. Spark propagates null through
     arithmetic like SQL; Perl numifies undef to 0. Reproducing the Perl
     behaviour is the requirement.

  3. The final `orderBy` is mandatory and total. A Spark DataFrame has no row
     order until you ask for one, and the legacy job's output order is part of
     its contract.
"""
from __future__ import annotations

from typing import Dict

from pyspark.sql import DataFrame, SparkSession
from pyspark.sql import functions as F
from pyspark.sql.types import DecimalType, StringType, StructField, StructType

COMMISSION_BPS = "0.015"
MONEY = DecimalType(18, 6)

TRANSACTION_SCHEMA = StructType([
    StructField("txn_id", StringType(), False),
    StructField("customer_id", StringType(), True),
    StructField("txn_date", StringType(), True),
    StructField("amount", StringType(), True),
    StructField("currency", StringType(), True),
    StructField("channel", StringType(), True),
])

FX_SCHEMA = StructType([
    StructField("currency", StringType(), False),
    StructField("rate_to_usd", StringType(), True),
])


def run(spark: SparkSession, inputs: Dict[str, str]) -> DataFrame:
    # Explicit schemas: inferSchema costs an extra pass and would type
    # zero-padded identifiers as integers.
    txn = spark.read.csv(inputs["transactions"], header=True, schema=TRANSACTION_SCHEMA)
    fx = spark.read.csv(inputs["fx_rates"], header=True, schema=FX_SCHEMA)

    fx = fx.select(
        F.col("currency").alias("fx_currency"),
        F.col("rate_to_usd").cast(MONEY).alias("rate"),
    )

    joined = txn.join(fx, txn["currency"] == fx["fx_currency"], how="left")

    # Perl: `no warnings 'uninitialized'` - an unrated currency is undef, which
    # numifies to 0. Without this coalesce Spark would null out the whole row
    # and the channel totals would silently shrink.
    rate = F.coalesce(F.col("rate"), F.lit(0).cast(MONEY))
    converted = (F.col("amount").cast(MONEY) * rate).cast(MONEY)

    priced = joined.select(
        F.col("channel"),
        F.col("currency"),
        converted.alias("usd"),
        (converted * F.lit(COMMISSION_BPS).cast(MONEY)).cast(MONEY).alias("commission"),
    )

    aggregated = priced.groupBy("channel", "currency").agg(
        F.count(F.lit(1)).alias("txn_count"),
        F.sum("usd").alias("total_usd"),
        F.sum("commission").alias("total_commission"),
    )

    return (aggregated
            .select(
                F.col("channel"),
                F.col("currency"),
                F.col("txn_count"),
                # printf("%.2f") - the legacy output contract, reproduced.
                F.format_number(F.col("total_usd").cast("double"), 2)
                 .alias("total_usd"),
                F.format_number(F.col("total_commission").cast("double"), 2)
                 .alias("total_commission"),
            )
            # Perl's `sort keys %usd` is a string sort over "channel|currency".
            .orderBy(F.col("channel").asc(), F.col("currency").asc()))


def main() -> int:
    import argparse
    import sys
    from pathlib import Path

    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
    from config import SAMPLE_DIR

    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--transactions", default=str(SAMPLE_DIR / "transactions.csv"))
    ap.add_argument("--fx-rates", default=str(SAMPLE_DIR / "fx_rates.csv"))
    ap.add_argument("--output", help="write Parquet here instead of showing")
    args = ap.parse_args()

    spark = (SparkSession.builder
             .appName("fx_revenue_calc")
             .config("spark.sql.shuffle.partitions", "8")
             .getOrCreate())
    try:
        frame = run(spark, {"transactions": args.transactions,
                            "fx_rates": args.fx_rates})
        if args.output:
            frame.write.mode("overwrite").parquet(args.output)
        else:
            frame.show(50, truncate=False)
    finally:
        spark.stop()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
